insert into public.products
  (id, name, slug, description, price_ngn, category, image_urls, stock, is_featured, created_at)
values
  ('10000000-0000-4000-8000-000000000001', 'Apple iPhone 13 128GB', 'apple-iphone-13-128gb', 'The iPhone 13 pairs a bright 6.1-inch Super Retina XDR display with the fast A15 Bionic chip and a dual 12MP camera system. Unit is brand new, sealed, factory unlocked and ready for any Nigerian network. Box contents: iPhone, USB-C to Lightning cable, documentation.', 649000, 'phones', array['/products/apple-iphone-13-128gb.svg', '/products/apple-iphone-13-128gb-2.svg'], 8, true, '2026-09-20T10:00:00Z'),
  ('10000000-0000-4000-8000-000000000002', 'Samsung Galaxy A55 5G 8/256GB', 'samsung-galaxy-a55-5g', 'A dependable mid-ranger with a 6.6-inch 120Hz AMOLED screen, 50MP OIS camera and a 5,000mAh battery that easily lasts a full day. 8GB RAM with 256GB storage, dual-SIM 5G support and Samsungs four generations of Android updates.', 480000, 'phones', array['/products/samsung-galaxy-a55-5g.svg', '/products/samsung-galaxy-a55-5g-2.svg'], 12, false, '2026-09-12T10:00:00Z'),
  ('10000000-0000-4000-8000-000000000003', 'Tecno Camon 30 8/256GB', 'tecno-camon-30', 'Popular all-rounder with a 6.78-inch AMOLED display, 50MP selfie camera and 70W fast charging. Great value for everyday use, streaming and social media, with 8GB RAM (plus virtual expansion) and 256GB of storage.', 335000, 'phones', array['/products/tecno-camon-30.svg', '/products/tecno-camon-30-2.svg'], 15, false, '2026-09-05T10:00:00Z'),
  ('10000000-0000-4000-8000-000000000004', 'Xiaomi Redmi Note 13 Pro 8/256GB', 'xiaomi-redmi-note-13-pro', '200MP main camera, 6.67-inch AMOLED panel and 67W turbo charging at a price that makes sense. The battery comfortably covers a heavy day, and MIUI extras like split-screen make multitasking simple.', 385000, 'phones', array['/products/xiaomi-redmi-note-13-pro.svg', '/products/xiaomi-redmi-note-13-pro-2.svg'], 10, false, '2026-08-28T10:00:00Z'),
  ('10000000-0000-4000-8000-000000000005', 'Apple MacBook Air 13-inch M2 8/256GB', 'macbook-air-13-m2', 'Fanless, silent and seriously fast. The M2 MacBook Air handles coding, design, video calls and dozens of browser tabs while still returning all-day battery life. 13.6-inch Liquid Retina display, MagSafe charging and two Thunderbolt ports.', 1150000, 'laptops', array['/products/macbook-air-13-m2.svg', '/products/macbook-air-13-m2-2.svg'], 5, true, '2026-09-25T10:00:00Z'),
  ('10000000-0000-4000-8000-000000000006', 'HP EliteBook 840 G8 i7/16/512', 'hp-elitebook-840-g8', 'Business-class ultrabook: Intel Core i7, 16GB RAM and a fast 512GB NVMe SSD. Thin, light and built to survive daily commuting, with a comfortable backlit keyboard and a crisp 14-inch full-HD screen. Excellent for office work and remote roles.', 735000, 'laptops', array['/products/hp-elitebook-840-g8.svg', '/products/hp-elitebook-840-g8-2.svg'], 6, false, '2026-09-15T10:00:00Z'),
  ('10000000-0000-4000-8000-000000000007', 'Dell Latitude 5420 i5/16/512', 'dell-latitude-5420', 'Reliable 14-inch workhorse with an 11th-gen Intel Core i5, 16GB RAM and 512GB SSD. Fast boot, excellent keyboard and all the ports you need (HDMI, USB-C, USB-A). A smart pick for students, developers and business users.', 665000, 'laptops', array['/products/dell-latitude-5420.svg', '/products/dell-latitude-5420-2.svg'], 7, false, '2026-09-02T10:00:00Z'),
  ('10000000-0000-4000-8000-000000000008', 'Apple AirPods Pro 2 USB-C', 'airpods-pro-2-usb-c', 'Active noise cancellation that genuinely works on Lagos traffic, Adaptive Transparency, and a battery case with Find My support. Sweat and water resistant, with personalised spatial audio for movies and music.', 289000, 'audio', array['/products/airpods-pro-2-usb-c.svg', '/products/airpods-pro-2-usb-c-2.svg'], 20, true, '2026-09-22T10:00:00Z'),
  ('10000000-0000-4000-8000-000000000009', 'Sony WH-1000XM5 Wireless Headphones', 'sony-wh-1000xm5', 'Among the best noise-cancelling headphones you can buy: eight microphones, 30-hour battery life and superb call quality. Light on the head, folds flat, and pairs with two devices at once so you can switch between laptop and phone.', 395000, 'audio', array['/products/sony-wh-1000xm5.svg', '/products/sony-wh-1000xm5-2.svg'], 9, false, '2026-09-08T10:00:00Z'),
  ('10000000-0000-4000-8000-000000000010', 'JBL Flip 6 Bluetooth Speaker', 'jbl-flip-6', 'Pocket-sized speaker with surprisingly big sound, IP67 waterproof/dustproof rating and 12 hours of playtime. Pair two Flip 6 speakers for stereo sound at events, or use it as a loud speakerphone at the desk.', 138000, 'audio', array['/products/jbl-flip-6.svg', '/products/jbl-flip-6-2.svg'], 14, false, '2026-08-20T10:00:00Z'),
  ('10000000-0000-4000-8000-000000000011', 'Samsung Galaxy Watch 6 44mm', 'samsung-galaxy-watch-6-44mm', 'Sleek smartwatch with a crisp Super AMOLED display, sleep and heart-rate tracking, GPS and 40+ workout modes. Works with any recent Android phone and easily lasts a day and a half on a charge.', 215000, 'accessories', array['/products/samsung-galaxy-watch-6-44mm.svg', '/products/samsung-galaxy-watch-6-44mm-2.svg'], 11, true, '2026-09-18T10:00:00Z'),
  ('10000000-0000-4000-8000-000000000012', 'Anker 737 PowerBank 24,000mAh 140W', 'anker-737-powerbank-24000mah', 'High-capacity power bank with a 140W USB-C port that can charge a MacBook, plus a smart digital display showing remaining time. Charges itself fully in about an hour. Cabin-friendly and built for blackouts.', 98000, 'accessories', array['/products/anker-737-powerbank-24000mah.svg', '/products/anker-737-powerbank-24000mah-2.svg'], 18, false, '2026-08-15T10:00:00Z')
